package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class MajorIncidentsAcceptance {
 static String api(String id){return "/api/openservice/incidents/"+id+"/major";}
 static Map<String,Object> page(WorkflowSupport h,String id)throws Exception{return get(h,api(id),"admin");}
 static Map<String,Object> get(WorkflowSupport h,String path,String user)throws Exception{return ProblemInvestigationsAcceptance.result(h.get(path,auth(user)));}
 static Map<String,Object> body(WorkflowSupport h,String id,String operation,Map<String,Object> fields)throws Exception{var p=page(h,id);var b=map("operation",operation,"revision",object(p.get("major")).get("revision"),"record_revision",ProblemInvestigationsAcceptance.revision(object(p.get("incident"))));b.putAll(fields);return b;}
 static Map<String,Object> send(WorkflowSupport h,String id,String operation,Map<String,Object> fields,String user)throws Exception{return ProblemInvestigationsAcceptance.result(h.json("POST",api(id),body(h,id,operation,fields),auth(user)));}
 static void fail(WorkflowSupport h,String id,String operation,Map<String,Object> fields,String user,int status)throws Exception{var r=h.json("POST",api(id),body(h,id,operation,fields),auth(user));assertEquals(status,r.statusCode(),html(r));}
 static Map<String,Object> reason(){return map("reason","Reviewed decision");}
 static Map<String,Object> related(WorkflowSupport h,String child)throws Exception{return map("child_id",child,"child_revision",ProblemInvestigationsAcceptance.revision(get(h,"/api/now/table/incident/"+child,"admin")));}
 static String incident(WorkflowSupport h)throws Exception{return h.add("incident").get("sys_id").toString();}
 static void setup(WorkflowSupport h)throws Exception{h.account("MajorCommander","agent");h.account("MajorOther","agent");h.account("MajorReader","reader");h.account("MajorRequester","requester");}
 static void propose(WorkflowSupport h,String id)throws Exception{send(h,id,"propose",map("reason","Widespread disruption","impact","Customers cannot use checkout"),"MajorOther");}
 static void accept(WorkflowSupport h,String id)throws Exception{send(h,id,"accept",map("reason","Confirmed outage","impact","Checkout unavailable","commander","MajorCommander"),"admin");}
 static void review(WorkflowSupport h,String id)throws Exception{send(h,id,"review",map("cause","Database failover","lessons","Improve failover drills","actions","Run a recovery exercise"),"MajorCommander");}
 static void run(WorkflowSupport h)throws Exception{
  setup(h);String id=incident(h),child=incident(h);assertEquals("",object(page(h,id).get("major")).get("status"));propose(h,id);assertEquals("candidate",object(page(h,id).get("major")).get("status"));assertEquals(409,h.json("DELETE","/api/now/table/incident/"+id,map(),auth("admin")).statusCode());accept(h,id);assertEquals("2",object(page(h,id).get("incident")).get("state"));
  var publication=body(h,id,"publish",map("message","Investigating checkout <script>"));ProblemInvestigationsAcceptance.result(h.json("POST",api(id),publication,auth("MajorCommander")));assertEquals(409,h.json("POST",api(id),publication,auth("MajorCommander")).statusCode());assertEquals(1,objects(page(h,id).get("updates")).size());send(h,id,"link",related(h,child),"MajorCommander");var childPage=page(h,child);assertEquals(true,childPage.get("has_parent"));assertEquals(id,object(object(childPage.get("parent")).get("incident")).get("sys_id"));assertEquals("Investigating checkout <script>",objects(object(childPage.get("parent")).get("updates")).getFirst().get("message"));fail(h,id,"demote",reason(),"admin",400);
  for(String target:List.of("1","6","7"))WorkTasksAcceptance.state(h,id,target,409);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var row=Service.record(db,"incident",id);object(row.get("data")).put("state","6");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,row)).status);}
  send(h,id,"restore",map("outcome","Failed over to healthy database"),"MajorCommander");assertEquals("6",object(page(h,id).get("incident")).get("state"));WorkTasksAcceptance.state(h,id,"2",409);fail(h,id,"close",reason(),"MajorCommander",400);review(h,id);String owner;try(var db=h.store.open()){owner=RecordAccess.owner(db,"admin");}ProblemInvestigationsAcceptance.access(h,"incident",child,"private",owner);fail(h,id,"close",reason(),"MajorCommander",409);assertTrue(objects(get(h,api(id),"MajorCommander").get("children")).isEmpty());ProblemInvestigationsAcceptance.access(h,"incident",child,"workspace","");assertEquals("reviewed",object(page(h,id).get("major")).get("status"));
  send(h,id,"reopen",reason(),"MajorCommander");assertEquals("",object(page(h,id).get("major")).get("review_cause"));assertEquals("2",object(page(h,id).get("incident")).get("state"));send(h,id,"restore",map("outcome","Service stable after retry"),"MajorCommander");review(h,id);send(h,id,"unlink",related(h,child),"MajorCommander");assertEquals("restored",object(page(h,id).get("major")).get("status"));review(h,id);send(h,id,"link",related(h,child),"MajorCommander");assertEquals("restored",object(page(h,id).get("major")).get("status"));review(h,id);
  WorkTasksAcceptance.state(h,child,"2",200);WorkTasksAcceptance.state(h,child,"6",200);new Store(h.environment);send(h,id,"close",reason(),"MajorCommander");assertEquals("closed",object(page(h,id).get("major")).get("status"));assertEquals("7",object(page(h,id).get("incident")).get("state"));WorkTasksAcceptance.state(h,child,"2",409);WorkTasksAcceptance.state(h,child,"7",200);assertEquals(409,h.json("DELETE","/api/now/table/incident/"+id,map(),auth("admin")).statusCode());assertEquals(409,h.json("DELETE","/api/now/table/incident/"+child,map(),auth("admin")).statusCode());fail(h,id,"unlink",related(h,child),"MajorCommander",400);send(h,id,"unlink",related(h,child),"admin");assertEquals(204,h.json("DELETE","/api/now/table/incident/"+id,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_major_update"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_major_incident"));}
 }
 static void decisions(WorkflowSupport h)throws Exception{
  setup(h);String id=incident(h);propose(h,id);fail(h,id,"accept",map("reason","Accept","impact","Impact","commander","MajorCommander"),"MajorOther",403);send(h,id,"reject",reason(),"admin");assertEquals("declined",object(page(h,id).get("major")).get("status"));propose(h,id);accept(h,id);send(h,id,"assign",map("reason","Handoff","commander","MajorOther"),"admin");fail(h,id,"publish",map("message","Old command"),"MajorCommander",403);send(h,id,"publish",map("message","Current command"),"MajorOther");send(h,id,"restore",map("outcome","Restored"),"MajorOther");send(h,id,"assign",map("reason","Handoff back","commander","MajorCommander"),"admin");review(h,id);send(h,id,"assign",map("reason","Review handoff","commander","admin"),"admin");assertEquals("restored",object(page(h,id).get("major")).get("status"));send(h,id,"reopen",reason(),"admin");send(h,id,"demote",reason(),"admin");assertEquals("declined",object(page(h,id).get("major")).get("status"));assertEquals("2",object(page(h,id).get("incident")).get("state"));assertEquals(204,h.json("DELETE","/api/now/table/incident/"+id,map(),auth("admin")).statusCode());
  id=incident(h);propose(h,id);WorkTasksAcceptance.state(h,id,"2",200);WorkTasksAcceptance.state(h,id,"6",200);fail(h,id,"accept",map("reason","Late","impact","Impact","commander","MajorCommander"),"admin",400);send(h,id,"reject",reason(),"admin");fail(h,id,"propose",map("reason","Closed","impact","Impact"),"admin",400);
  String root=incident(h),child=incident(h);propose(h,root);accept(h,root);send(h,root,"link",related(h,child),"admin");fail(h,child,"propose",map("reason","Nested","impact","Impact"),"admin",400);send(h,root,"unlink",related(h,child),"admin");send(h,root,"demote",reason(),"admin");propose(h,root);accept(h,root);
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  setup(h);String id=incident(h),child=incident(h);var valid=body(h,id,"propose",map("reason","Disruption","impact","Impact"));
  for(String user:List.of("MajorReader","MajorRequester")){assertEquals(403,h.get(api(id),auth(user)).statusCode());assertEquals(403,h.json("POST",api(id),valid,auth(user)).statusCode());assertEquals(403,h.get("/api/openservice/major-incidents",auth(user)).statusCode());}
  assertEquals(404,h.get(api("f".repeat(32)),auth("admin")).statusCode());assertEquals(405,h.json("PATCH",api(id),valid,auth("admin")).statusCode());assertEquals(405,h.json("POST","/api/openservice/major-incidents",map(),auth("admin")).statusCode());for(String query:List.of("unexpected=1","q=a&q=b","limit=0","q="+"x".repeat(201)))assertEquals(400,h.get(api(id)+"?"+query,auth("admin")).statusCode());assertEquals(400,h.json("POST",api(id)+"?q=a",valid,auth("admin")).statusCode());assertEquals(400,h.json("POST",api(id),map(),auth("admin")).statusCode());var bad=new LinkedHashMap<>(valid);bad.put("operation","wrong");assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());bad=new LinkedHashMap<>(valid);bad.put("extra",true);assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());for(String key:List.of("revision","record_revision")){bad=new LinkedHashMap<>(valid);bad.put(key,1);assertEquals(409,h.json("POST",api(id),bad,auth("admin")).statusCode());}
  for(String key:List.of("reason","impact"))for(Object value:List.of(" ","x".repeat(4001),1)){bad=new LinkedHashMap<>(valid);bad.put(key,value);assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());}
  for(String query:List.of("unexpected=1","status=bad","limit=0","limit=101","offset=-1","status=all&status=active"))assertEquals(400,h.get("/api/openservice/major-incidents?"+query,auth("admin")).statusCode());
  for(String operation:List.of("reject","demote","reopen","close"))fail(h,id,operation,reason(),"admin",400);fail(h,id,"accept",map("reason","Accept","impact","Impact","commander","MajorCommander"),"admin",400);fail(h,id,"assign",map("reason","Handoff","commander","MajorCommander"),"admin",400);fail(h,id,"publish",map("message","Update"),"admin",400);fail(h,id,"link",related(h,child),"admin",400);fail(h,id,"unlink",related(h,child),"admin",400);fail(h,id,"restore",map("outcome","Restored"),"admin",400);fail(h,id,"review",map("cause","Cause","lessons","Lessons","actions","Actions"),"admin",400);
  propose(h,id);fail(h,id,"propose",map("reason","Repeat","impact","Impact"),"admin",400);for(String commander:List.of("missing","MajorReader","MajorRequester"," "))fail(h,id,"accept",map("reason","Accept","impact","Impact","commander",commander),"admin",400);accept(h,id);
  fail(h,id,"link",related(h,id),"admin",400);var stale=related(h,child);stale.put("child_revision",1);fail(h,id,"link",stale,"admin",409);fail(h,id,"unlink",related(h,child),"admin",404);fail(h,id,"link",map("child_id","f".repeat(32),"child_revision",0),"admin",404);WorkTasksAcceptance.state(h,child,"2",200);WorkTasksAcceptance.state(h,child,"6",200);fail(h,id,"link",related(h,child),"admin",400);WorkTasksAcceptance.state(h,child,"2",200);propose(h,child);fail(h,id,"link",related(h,child),"admin",400);send(h,child,"reject",reason(),"admin");send(h,id,"link",related(h,child),"admin");fail(h,id,"link",related(h,child),"admin",400);
  String other=incident(h);propose(h,other);accept(h,other);fail(h,other,"link",related(h,child),"admin",400);send(h,id,"unlink",related(h,child),"admin");fail(h,id,"link",related(h,other),"admin",400);
 }
 static void authority(WorkflowSupport h)throws Exception{
  setup(h);String id=incident(h),child=incident(h),admin,other,commander;Map<String,Object> original;
  try(var db=h.store.open()){admin=RecordAccess.owner(db,"admin");other=RecordAccess.owner(db,"MajorOther");commander=RecordAccess.owner(db,"MajorCommander");original=Service.schema(db,"incident");}
  propose(h,id);ProblemInvestigationsAcceptance.access(h,"incident",id,"private",other);fail(h,id,"accept",map("reason","Accept","impact","Impact","commander","MajorCommander"),"admin",404);assertEquals("candidate",object(page(h,id).get("major")).get("status"));ProblemInvestigationsAcceptance.access(h,"incident",id,"workspace","");
  for(String clause:List.of("active=0","password_reset_required=1","role='reader'")){try(var db=h.store.open()){db.update("UPDATE os_user SET "+clause+" WHERE user_id=?",commander);db.connection.commit();}fail(h,id,"accept",map("reason","Accept","impact","Impact","commander","MajorCommander"),"admin",400);try(var db=h.store.open()){db.update("UPDATE os_user SET active=1,password_reset_required=0,role='agent' WHERE user_id=?",commander);db.connection.commit();}}
  accept(h,id);send(h,id,"link",related(h,child),"admin");send(h,id,"publish",map("message","Restricted root update"),"admin");ProblemInvestigationsAcceptance.access(h,"incident",child,"private",admin);var visible=get(h,api(id),"MajorCommander");assertTrue(objects(visible.get("children")).isEmpty());assertFalse(JSON.writeValueAsString(visible).contains(child));ProblemInvestigationsAcceptance.access(h,"incident",child,"workspace","");ProblemInvestigationsAcceptance.access(h,"incident",id,"private",admin);visible=get(h,api(child),"MajorCommander");assertEquals(true,visible.get("has_parent"));assertNull(visible.get("parent"));assertFalse(JSON.writeValueAsString(visible).contains("Restricted root update"));assertFalse(JSON.writeValueAsString(visible).contains(id));assertEquals(404,h.get(api(id),auth("MajorCommander")).statusCode());assertEquals(0,((Number)get(h,"/api/openservice/major-incidents","MajorCommander").get("total")).intValue());ProblemInvestigationsAcceptance.access(h,"incident",id,"workspace","");
  for(String field:List.of("description","state")){var changed=new LinkedHashMap<>(original);changed.put("field_rules",map(field,map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{assertEquals(403,h.get(api(id),auth("MajorCommander")).statusCode());assertEquals(0,((Number)get(h,"/api/openservice/major-incidents","MajorCommander").get("total")).intValue());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}
  var changed=new LinkedHashMap<>(original);changed.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{assertEquals(403,h.get(api(id),auth("MajorCommander")).statusCode());assertEquals(0,((Number)get(h,"/api/openservice/major-incidents","MajorCommander").get("total")).intValue());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  changed=new LinkedHashMap<>(original);changed.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{fail(h,id,"publish",map("message","Denied"),"MajorCommander",403);assertEquals(false,get(h,api(id),"MajorCommander").get("can_update"));}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  changed=new LinkedHashMap<>(original);changed.put("field_rules",map("short_description",map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{assertTrue(objects(object(get(h,api(id),"MajorCommander").get("search")).get("items")).isEmpty());assertEquals(400,h.get(api(id)+"?unexpected=1",auth("MajorCommander")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  changed=new LinkedHashMap<>(original);changed.put("field_rules",map("state",map("write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{fail(h,id,"restore",map("outcome","Cannot persist"),"MajorCommander",403);assertEquals("declared",object(page(h,id).get("major")).get("status"));}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  try(var db=h.store.open()){db.update("UPDATE os_user SET role='reader' WHERE user_id=?",commander);db.connection.commit();}assertEquals(403,h.get(api(id),auth("MajorCommander")).statusCode());send(h,id,"assign",map("reason","Recover revoked commander","commander","MajorOther"),"admin");send(h,id,"publish",map("message","Recovered staff update"),"MajorOther");assertTrue(objects(get(h,api(id),"MajorOther").get("staff")).isEmpty());try(var db=h.store.open()){db.update("UPDATE os_user SET role='agent' WHERE user_id=?",commander);db.connection.commit();}
  String candidate=incident(h);propose(h,candidate);var queue=get(h,"/api/openservice/major-incidents?limit=1","MajorOther");assertEquals(2,((Number)queue.get("total")).intValue());assertEquals(1,objects(queue.get("items")).size());assertEquals(1,queue.get("next_offset"));assertNull(get(h,"/api/openservice/major-incidents?offset=1&limit=1","MajorOther").get("next_offset"));assertEquals(1,((Number)get(h,"/api/openservice/major-incidents?status=candidate","admin").get("total")).intValue());assertEquals(0,((Number)get(h,"/api/openservice/major-incidents?status=closed","admin").get("total")).intValue());send(h,candidate,"reject",reason(),"admin");assertEquals(1,((Number)get(h,"/api/openservice/major-incidents?status=declined","admin").get("total")).intValue());assertEquals(2,((Number)get(h,"/api/openservice/major-incidents?status=all","admin").get("total")).intValue());
 }
 static void capacityAndGates(WorkflowSupport h)throws Exception{
  setup(h);String id=incident(h),child=incident(h);propose(h,id);accept(h,id);send(h,id,"link",related(h,child),"admin");
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=1;n<100;n++){String target=Service.create(db,"incident",map("short_description","Related outage "+n),"admin").get("sys_id").toString();db.update("INSERT INTO os_major_link(child_id,major_id) VALUES(?,?)",target,id);}for(int n=1;n<100;n++)db.update("INSERT INTO os_major_update(update_id,parent_id,message,actor_id,ordinal,created) VALUES(?,?,?,?,?,?)",Values.id(),id,"Prior update "+n,"unavailable",n,now());db.connection.commit();}
  send(h,id,"publish",map("message","x".repeat(4000)),"admin");assertEquals(100,objects(page(h,id).get("updates")).size());assertEquals("Unavailable account",objects(page(h,id).get("updates")).getFirst().get("author"));fail(h,id,"publish",map("message","Too many"),"admin",400);assertEquals(100,objects(page(h,id).get("children")).size());String extra=incident(h);fail(h,id,"link",related(h,extra),"admin",400);assertEquals(1,objects(object(get(h,api(id)+"?q=Related%20outage&limit=1","admin").get("search")).get("items")).size());
  String bounded=incident(h);propose(h,bounded);accept(h,bounded);String group=h.add("sys_user_group").get("sys_id").toString();var config=WorkTasksAcceptance.command(h,bounded,"configure","");config.put("close_at","7");WorkTasksAcceptance.send(h,bounded,config,"admin");String task=WorkTasksAcceptance.create(h,bounded,group,List.of(),true);send(h,bounded,"restore",map("outcome","Service restored"),"MajorCommander");review(h,bounded);fail(h,bounded,"close",reason(),"MajorCommander",409);assertEquals("reviewed",object(page(h,bounded).get("major")).get("status"));WorkTasksAcceptance.act(h,bounded,task,"claim","admin","");WorkTasksAcceptance.act(h,bounded,task,"complete","admin","Recovery drill verified");send(h,bounded,"close",reason(),"MajorCommander");assertEquals("closed",object(page(h,bounded).get("major")).get("status"));
  String gated=incident(h);propose(h,gated);Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}var changed=new LinkedHashMap<>(original);changed.put("version",Approvals.version(original)+1);changed.put("transition_rules",map("2",map("min_approvals",1)));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{fail(h,gated,"accept",map("reason","Accept","impact","Impact","commander","MajorCommander"),"admin",409);assertEquals("candidate",object(page(h,gated).get("major")).get("status"));}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  accept(h,gated);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var row=Service.record(db,"incident",gated);object(row.get("data")).put("state",null);assertEquals(409,assertThrows(Failure.class,()->MajorIncidents.guard(db,row)).status);}
  var form=body(h,gated,"publish",map("message","Form publication"));assertEquals(302,h.protectedForm("/record/incident/"+gated+"/major",form,auth("admin")).statusCode());form=body(h,gated,"link",related(h,extra));assertEquals(302,h.protectedForm("/record/incident/"+gated+"/major",form,auth("admin")).statusCode());form=body(h,gated,"unlink",related(h,extra));form.put("child_revision","invalid");assertEquals(400,h.protectedForm("/record/incident/"+gated+"/major",form,auth("admin")).statusCode());
 }
}
